                                                            {c.options
                                                                    ?.length > 4 &&
                                                                "…"}{" "}
                                                            •{" "}
                                                            {c.multipleSelection
                                                                ? "Multi-select"
                                                                : "Single"}
                                                    </span>
                                                    )}

                                                {c.type === "RATING" && (
                                                    <span
