                                                        Length:{" "}
                                                            {c.minLength ??
                                                                "any"}
                                                            –
                                                            {c.maxLength ??
                                                                "any"}
                                                    </span>
                                                    )}

                                                {c.type === "NUMERIC" && (
                                                    <span
                                                        style={
                                                            styles.metaChip
                                                        }
                                                    >
                                                        {c.integerOnly
                                                            ? "Integer"
                                                            : "Float"}{" "}
                                                        •{" "}
                                                        {c.minValue ??
                                                            "any"}
                                                        –
                                                        {c.maxValue ??
                                                            "any"}
                                                    </span>
                                                )}

                                                {c.type ===
                                                    "IMAGE_HIGHLIGHT" && (
                                                        <span
                                                            style={
                                                                styles.metaChip
                                                            }
                                                        >
                                                        Max annotations:{" "}
                                                            {
                                                                c.numberOfAnnotations
                                                            }
                                                    </span>
                                                    )}

                                                {c.type ===
                                                    "CODE_EDIT" && (
                                                        <span
                                                            style={
                                                                styles.metaChip
                                                            }
                                                        >
                                                        Participant edits code
                                                        directly
                                                    </span>
                                                    )}
                                            </div>

                                            <div
                                                style={
                                                    styles.accordionFooter
                                                }
                                            >
                                                <button
                                                    style={
                                                        styles.deleteButton
                                                    }
                                                    onClick={() =>
                                                        handleDelete(c.id)
                                                    }
                                                >
                                                    🗑 Delete
                                                </button>
                                            </div>
                                        </div>
                                    )}
                                </div>
                            );
                        })}
                    </div>
                )}
            </div>

            {/* 🔥 BOTTOM FULL-WIDTH CREATE BUTTON */}
            <div style={styles.bottomSaveContainer}>
                <button
                    onClick={handleSaveTemplate}
                    className="create-btn"
                    style={{
                        ...styles.createBtn,
