                                    <div style={styles.inputGroup}>
                                        <label style={styles.label}>
                                            Description (optional)
                                        </label>
                                        <textarea
                                            style={styles.textarea}
                                            value={
                                                newCriterion.description
                                            }
                                            onChange={(e) =>
                                                setNewCriterion({
                                                    ...newCriterion,
                                                    description:
                                                    e.target.value,
                                                })
                                            }
                                            rows={2}
                                        />
                                    </div>

                                    <div style={styles.inlineRow}>
                                        <div
                                            style={{
                                                ...styles.inputGroup,
                                                flex: 1,
                                            }}
                                        >
                                            <label style={styles.label}>
                                                Priority *
                                            </label>
                                            <input
                                                type="number"
                                                style={styles.input}
                                                value={
                                                    newCriterion.priorityOrder
