                                                    Open Ended
                                                </option>
                                                <option value="NUMERIC">
                                                    Numeric
                                                </option>
                                                <option value="CODE_EDIT">
                                                    Code Edit
                                                </option>
                                                <option value="IMAGE_HIGHLIGHT">
                                                    Image Highlight
                                                </option>
                                            </select>
