                                                        styles.inlineRow
                                                    }
                                                >
                                                    <div
                                                        style={{
                                                            ...styles.inputGroup,
                                                            flex: 1,
                                                        }}
                                                    >
                                                        <label
                                                            style={
                                                                styles.label
                                                            }
                                                        >
                                                            Min length
                                                        </label>
                                                        <input
                                                            type="number"
                                                            style={
                                                                styles.input
                                                            }
                                                            value={
                                                                newCriterion.minLength
                                                            }
                                                            onChange={(e) =>
                                                                setNewCriterion(
                                                                    {
                                                                        ...newCriterion,
                                                                        minLength:
                                                                        e
                                                                            .target
                                                                            .value,
                                                                    }
                                                                )
                                                            }
                                                        />
                                                    </div>

                                                    <div
                                                        style={{
                                                            ...styles.inputGroup,
                                                            flex: 1,
                                                        }}
                                                    >
                                                        <label
                                                            style={
                                                                styles.label
                                                            }
                                                        >
                                                            Max length
                                                        </label>
                                                        <input
                                                            type="number"
                                                            style={
                                                                styles.input
                                                            }
                                                            value={
                                                                newCriterion.maxLength
                                                            }
                                                            onChange={(e) =>
                                                                setNewCriterion(
                                                                    {
                                                                        ...newCriterion,
                                                                        maxLength:
                                                                        e
                                                                            .target
                                                                            .value,
                                                                    }
                                                                )
                                                            }
                                                        />
                                                    </div>
                                                </div>
                                            )}

                                        {/* NUMERIC */}
                                        {newCriterion.type ===
                                            "NUMERIC" && (
                                                <>
                                                    <label
                                                        style={
                                                            styles.checkboxRow
                                                        }
                                                    >
                                                        <input
                                                            type="checkbox"
                                                            checked={
                                                                newCriterion.integerOnly
                                                            }
                                                            onChange={(e) =>
                                                                setNewCriterion(
                                                                    {
                                                                        ...newCriterion,
                                                                        integerOnly:
                                                                        e
                                                                            .target
                                                                            .checked,
                                                                    }
                                                                )
                                                            }
                                                            style={
                                                                styles.checkbox
                                                            }
                                                        />
                                                        Integer only
                                                    </label>

                                                    <div
                                                        style={
                                                            styles.inlineRow
                                                        }
                                                    >
                                                        <div
                                                            style={{
                                                                ...styles.inputGroup,
                                                                flex: 1,
                                                            }}
                                                        >
                                                            <label
                                                                style={
                                                                    styles.label
                                                                }
                                                            >
                                                                Min
                                                            </label>
                                                            <input
                                                                type="number"
                                                                style={
                                                                    styles.input
                                                                }
                                                                value={
                                                                    newCriterion.minValue
                                                                }
                                                                onChange={(e) =>
                                                                    setNewCriterion(
                                                                        {
                                                                            ...newCriterion,
                                                                            minValue:
                                                                            e
                                                                                .target
                                                                                .value,
                                                                        }
                                                                    )
                                                                }
                                                            />
                                                        </div>
                                                        <div
                                                            style={{
                                                                ...styles.inputGroup,
                                                                flex: 1,
                                                            }}
                                                        >
                                                            <label
                                                                style={
                                                                    styles.label
                                                                }
                                                            >
                                                                Max
                                                            </label>
                                                            <input
                                                                type="number"
                                                                style={
                                                                    styles.input
                                                                }
                                                                value={
                                                                    newCriterion.maxValue
                                                                }
                                                                onChange={(e) =>
                                                                    setNewCriterion(
                                                                        {
                                                                            ...newCriterion,
                                                                            maxValue:
                                                                            e
                                                                                .target
                                                                                .value,
                                                                        }
                                                                    )
                                                                }
                                                            />
                                                        </div>
                                                    </div>
                                                </>
                                            )}

                                        {/* CODE EDIT */}
                                        {newCriterion.type ===
                                            "CODE_EDIT" && (
                                                <p style={styles.helperText}>
                                                    No extra settings.
                                                    Participants will edit the
                                                    code directly.
                                                </p>
                                            )}

                                        {/* IMAGE HIGHLIGHT */}
                                        {newCriterion.type ===
                                            "IMAGE_HIGHLIGHT" && (
                                                <div
                                                    style={
                                                        styles.inputGroup
                                                    }
                                                >
                                                    <label
                                                        style={styles.label}
                                                    >
                                                        Max annotations *
                                                    </label>
                                                    <input
                                                        type="number"
                                                        min={1}
                                                        style={
                                                            styles.input
                                                        }
                                                        value={
                                                            newCriterion.numberOfAnnotations
                                                        }
                                                        onChange={(e) =>
                                                            setNewCriterion(
                                                                {
                                                                    ...newCriterion,
                                                                    numberOfAnnotations:
                                                                    e
                                                                        .target
                                                                        .value,
                                                                }
                                                            )
                                                        }
                                                    />
                                                </div>
                                            )}
                                    </div>
                                )}
                            </div>

                            <div style={styles.modalFooter}>
                                <button
                                    style={styles.modalCancelButton}
                                    onClick={closeModal}
                                >
                                    Cancel
                                </button>
                                <button
                                    style={styles.modalCreateButton}
                                    onClick={handleCreateCriterion}
                                    disabled={savingCriterion}
                                >
                                    {savingCriterion
                                        ? "Saving..."
                                        : "Create"}
                                </button>
                            </div>
                        </div>
                    </div>
                </>
            )}

            {/* KEYFRAMES */}
            <style>
                {`
                    @keyframes floatParticle {
                        0% { transform: translateY(0); opacity: 0.3; }
                        50% { opacity: 0.9; }
                        100% { transform: translateY(-120vh); opacity: 0; }
                    }

                    @keyframes fadeToast {
                        0% { opacity: 0; transform: translateY(-6px); }
                        100% { opacity: 1; transform: translateY(0); }
                    }

                    @keyframes modalPop {
                        0% { opacity: 0; transform: scale(0.92) translateY(8px); }
                        100% { opacity: 1; transform: scale(1) translateY(0); }
                    }

                    @keyframes spin {
                        0% { transform: rotate(0deg); }
                        100% { transform: rotate(360deg); }
                    }
                `}
            </style>
        </div>
    );
}

